INSERT INTO autor (nom_autor , image_autor , historique_autor , lien_autor , id_type_autor) VALUE
	
-- ------------------------------ Diffusion (id_type_autor = 4) ------------------------------------------

-- A
	('ADN', '../img/diffusions/ADN.jpg', 'Animation Digital Network, abrégé ADN, anciennement Anime Digital Network, est une plate-forme de VoD et simulcast née de la fusion entre KZPlay, appartenant à Kazé, et Genzai, appartenant à Kana Home Video, ayant pour thématique la diffusion de séries et longs métrages d''animation japonaise et franco-belge.', 'https://fr.wikipedia.org/wiki/Animation_Digital_Network', 4),
	('Amazon Prime Video', '../img/diffusions/AmazonPrimeVideo.jpg', 'Prime Video (Amazon Prime Video, anciennement commercialisé sous les noms Amazon Instant Video et Amazon Video on Demand) est un service de vidéo à la demande créé par Amazon et présent dans de nombreux pays. Concurrent de Netflix, il propose des films, des séries et émissions de télévision à la location ou à l''achat. Les titres sélectionnés sont offerts gratuitement aux clients qui ont un abonnement Amazon Prime, un geste commercial qui a irrité certains consommateurs du Royaume-Uni où il a été vendu avec une augmentation non négociable de 61 % du prix de l''abonnement. Comme ses concurrents, Amazon a recherché une quantité d''offres exclusives pour différencier son service.', 'https://fr.wikipedia.org/wiki/Prime_Video', 4),

-- C
	('Crunchyroll', '../img/diffusions/Crunchyroll.jpg', 'Crunchyroll est un service de vidéo à la demande américain par abonnement appartenant à Sony Corporation. Le service distribue principalement des films et des séries télévisées produits par des médias d''Asie de l''Est, y compris des dessins animés japonais. Crunchyroll édite également des mangas et des jeux mobiles. Lancé mi-2006 par un groupe d''étudiants diplômés de l''Université de Californie à Berkeley en 2006, les services de Crunchyroll se sont progressivement développés pour compter plus de 100 millions d''utilisateurs enregistrés, répartis dans plus de 200 pays ou territoires à travers le monde, dont quatre millions d''utilisateurs abonnés.', 'https://fr.wikipedia.org/wiki/Crunchyroll', 4),

-- N
	('Netflix', '../img/diffusions/Netflix.jpg', 'Netflix est une entreprise internationale américaine active dans le secteur de l''industrie du divertissement. Fondé en 1997 à Scotts Valley (Santa Cruz) par Reed Hastings et Marc Randolph, le groupe est spécialisé dans la distribution et l''exploitation d''œuvres cinématographiques et télévisuelles, notamment par le biais d''une plateforme destinée au service de vidéo à la demande. Son siège social se situe à Los Gatos en Californie. Initialement, l''entreprise est uniquement présente dans le secteur de l''exploitation commerciale, par la fourniture d''un service en ligne de location et d''achat de DVD, livrés à domicile. Elle propose ensuite la location de ces vidéos, moyennant un abonnement mensuel. Le service de vidéo à la demande par abonnement est lancé en 2007. Depuis, l''entreprise s''est lancée dans la distribution d''un grand nombre de films et de séries télévisées ainsi que de créations originales, auxquelles elle consacre des investissements importants.', 'https://fr.wikipedia.org/wiki/Netflix', 4),

-- S
	('Sony Pictures Entertainment', '../img/diffusions/SonyPicturesHomeEntertainment.jpg', 'Sony Pictures Entertainment Inc. (SPE) est une société américaine de la Sony Corporation of America, elle-même filiale du géant japonais de l''électronique grand public Sony. Son siège social est situé à Culver City en Californie.
Les activités de Sony Pictures sont la production et la distribution de films de cinéma et de programmes télévisés en salle, à la télévision, en vidéo et sur Internet.
Le studio compte parmi ses principales franchises Spider-Man, Men in Black, ou 21 Jump Street.', 'https://fr.wikipedia.org/wiki/Sony_Pictures_Entertainment', 4),

-- V
	('Viki', '../img/diffusions/Viki.jpg', 'Rakuten Viki est un service américain de vidéo à la demande spécialisé dans le streaming de contenus asiatiques. Il diffuse des émissions, séries et films provenant de la Corée du Sud, de la Chine, du Japon, de Taïwan et de la Thaïlande, et propose également du contenu original. La plateforme permet aux utilisateurs de visionner du contenu sous-titré dans plus de 200 langues. Basée à San Mateo, en Californie, la société possède également des bureaux à Singapour, Tokyo et Séoul.', 'https://fr.wikipedia.org/wiki/Viki_(service_de_streaming)', 4),

-- Y
	('YouTube', '../img/diffusions/Youtube.jpg', 'YouTube, prononcé en français [ ju.tyb] Écouterⓘ ou [ ju.tjub], est la principale plateforme de vidéos en ligne en Occident, sous forme d''application web et mobile. Les utilisateurs mettent en ligne, regardent en streaming, évaluent (avec un bouton j''aime), commentent et partagent le contenu, parfois en direct. Son site web figure dans la liste des sites web les plus visités.', 'https://fr.wikipedia.org/wiki/YouTube', 4);